Orchestrator Bridge for Upshalternal Hermes Agent
Connects existing Hermes Agent instance to the orchestrator
"""

import os
import sys
import logging
import subprocess
import json
from typing import Dict, Any

# Add orchestrator SDK to path
sys.path.insert(0, '/usr/local/lib/hermes-orchestrator')

from sdk.agent_base import AgentBase
from sdk.agent_config import AgentConfig

logger = logging.getLogger(__name__)

class UpshalternalBridgeAgent(AgentBase):
    """Bridge agent that connects Hermes Agent to orchestrator"""

    def __init__(self, config: AgentConfig):
        super().__init__(config)
        self.hermes_api_base = f"http://localhost:{config.metadata.get('port', 9120)}"
        logger.info(f"Bridge agent initialized for {config.agent_name}")

    def execute_task(self, task: Dict[str, Any]) -> Any:
        """
        Execute task by delegating to Hermes Agent

        Task types supported:
        - shell_command: Execute shell command via Hermes
        - file_operation: Read/write files
        - custom: Execute custom logic
        """

        task_type = task.get("type", "unknown")
        task_data = task.get("data", {})

        logger.info(f"Executing task type: {task_type}")

        if task_type == "shell_command":
            return self._execute_shell_command(task_data)
        elif task_type == "file_read":
            return self._read_file(task_data)
        elif task_type == "file_write":
            return self._write_file(task_data)
        elif task_type == "hermes_command":
            return self._execute_hermes_command(task_data)
        else:
            return {"error": f"Unknown task type: {task_type}"}

    def _execute_shell_command(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Execute a shell command"""
        command = data.get("command", "")
        if not command:
            return {"error": "No command provided"}

        try:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=300
            )
            return {
                "stdout": result.stdout,
                "stderr": result.stderr,
                "exit_code": result.returncode
            }
        except subprocess.TimeoutExpired:
            return {"error": "Command timed out"}
        except Exception as e:
            return {"error": str(e)}

    def _read_file(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Read a file"""
        path = data.get("path", "")
        if not path:
            return {"error": "No path provided"}

        try:
            with open(path, 'r') as f:
                content = f.read()
            return {"content": content}
        except Exception as e:
            return {"error": str(e)}

    def _write_file(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Write to a file"""
        path = data.get("path", "")
        content = data.get("content", "")

        if not path:
            return {"error": "No path provided"}

        try:
            with open(path, 'w') as f:
                f.write(content)
            return {"success": True}
        except Exception as e:
            return {"error": str(e)}

    def _execute_hermes_command(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Execute Hermes CLI command"""
        command = data.get("command", "")
        if not command:
            return {"error": "No command provided"}

        # Prepend hermes CLI
        full_command = f"hermes {command}"

        try:
            result = subprocess.run(
                full_command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=300
            )
            return {
                "stdout": result.stdout,
                "stderr": result.stderr,
                "exit_code": result.returncode
            }
        except Exception as e:
            return {"error": str(e)}

    def on_start(self):
        logger.info("Upshalternal bridge agent starting...")
        # Verify Hermes Agent is accessible
        try:
            result = subprocess.run(
                "hermes --version",
                shell=True,
                capture_output=True,
                text=True,
                timeout=10
            )
            logger.info(f"Hermes Agent version: {result.stdout.strip()}")
        except Exception as e:
            logger.error(f"Cannot access Hermes Agent: {e}")

    def on_stop(self):
        logger.info("Upshalternal bridge agent stopping...")


if __name__ == "__main__":
    # Setup logging
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(name)s - %(levelname)s - %(message)s'
    )

    # Create config from environment
    config = AgentConfig.from_env(
        agent_id="upshalternal",
        agent_name="Upshalternal AI CEO"
    )

    # Add capabilities
    config.capabilities = [
        "shell_command",
        "file_read",
        "file_write",
        "hermes_command"
    ]

    # Add metadata
    config.metadata = {
        "version": "1.0.0",
        "description": "Upshalternal Hermes Agent bridge to orchestrator",
        "port": 9120
    }

    # Create and run agent
    agent = UpshalternalBridgeAgent(config)
    agent.run()
